package com.servicehub.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity public class ServiceRequest { @Id @GeneratedValue private UUID id; @Column(unique=true) private String reference; private String title; @Column(length=4000) private String description; private String category; private String priority; @Enumerated(EnumType.STRING) private RequestStatus status=RequestStatus.NEW; @ManyToOne private AppUser customer; @ManyToOne private AppUser assignee; private Instant createdAt=Instant.now(); private Instant updatedAt=Instant.now(); public UUID getId(){return id;} public String getReference(){return reference;} public String getTitle(){return title;} public String getDescription(){return description;} public String getCategory(){return category;} public String getPriority(){return priority;} public RequestStatus getStatus(){return status;} public AppUser getCustomer(){return customer;} public AppUser getAssignee(){return assignee;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public void setReference(String x){reference=x;} public void setTitle(String x){title=x;} public void setDescription(String x){description=x;} public void setCategory(String x){category=x;} public void setPriority(String x){priority=x;} public void setStatus(RequestStatus x){status=x;updatedAt=Instant.now();} public void setCustomer(AppUser x){customer=x;} public void setAssignee(AppUser x){assignee=x;updatedAt=Instant.now();} }
